"""Original explanations and examples, in the mathematical order of book 21.1–21.4."""
import re
import sympy as s
lessons=[];models=[]
x,y,t=s.symbols('x y t',real=True)
def T(value):return s.latex(s.sympify(value))
def fmt(text):
 chunks=re.split(r'(\\\[.*?\\\]|\\\(.*?\\\))',text,flags=re.S);table=str.maketrans('⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿʸ','-0123456789ny')
 for i in range(0,len(chunks),2):chunks[i]=re.sub(r'(?:[A-Za-zλ][⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿʸ]+)+',lambda m:r'\('+re.sub(r'([A-Za-zλ])([⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿʸ]+)',lambda z:z[1]+'^{'+z[2].translate(table)+'}',m[0])+r'\)',chunks[i])
 return ''.join(chunks)
def D(*rows):
 rows=[part for row in rows for part in (row.split(r'\quad') if len(row)>100 and r'\quad' in row else [row])]
 return r'\[\begin{gathered}'+r'\\'.join(rows)+r'\end{gathered}\]'
def E(code,title,question,solution,kind,**data):
 uid='FDIFF-E-'+code;models.append(dict(id=uid,kind=kind,**data))
 return dict(title=title,question=fmt(question),solution=fmt(solution),verification=uid)
def L(key,title,summary,objective,before,ideas,method,mistakes,examples):
 lessons.append(dict(key=key,id='fp2_differentiation_'+key,title=title,summary=summary,objective=objective,before=before,ideas=fmt(ideas),method='<ol>'+''.join('<li>'+z+'</li>' for z in method)+'</ol>',mistakes=mistakes,examples=examples))
base='/courses/maths4u-9231-fp2/topics/fp2_differentiation_'
def before(key):return '<p>Complete <a href="'+base+key+'">the preceding lesson</a>. Review the chain, product and quotient rules and use exact values.</p>'
L('implicit','Implicit first and second derivatives','Differentiate the whole relation before inserting a point.',
 'Find first and second derivatives on a specified smooth implicit branch.',
 '<p>Review the chain and product rules, tangent gradients and implicit first derivatives from A Level Pure Mathematics. A branch means one local choice of y as a function of x.</p>',
 r'''<h3>Every occurrence of y depends on x</h3><p>Differentiate both sides of the defining relation. For example, differentiating a product xy gives y+xy′. Differentiating a power of y requires its chain factor y′. Do not insert the coordinates before differentiating: that would turn the relation into a numerical equality and destroy its derivative information.</p>'''+D(r'F(x,y)=0',r'F_x+F_y y^{\prime}=0',r'y^{\prime}=-\frac{F_x}{F_y}\qquad(F_y\ne0)')+r'''<p>The subscript notation is a compact summary: Fₓ means differentiating F with y temporarily fixed. In routine work you may differentiate the original equation directly. The condition Fᵧ≠0 ensures this local formula gives a finite gradient.</p><h3>Differentiate again with the product rule</h3>'''+D(r'F_{xx}+2F_{xy}y^{\prime}',r'\quad+F_{yy}(y^{\prime})^2+F_y y^{\prime\prime}=0')+r'''<p>The two mixed terms have different product-rule origins and combine to give the factor 2. When only values at a point are needed, first calculate y′ there, then insert x, y and that derivative into the twice-differentiated equation. This is often shorter than finding a large general formula for y′′.</p><h3>When the relation already contains a derivative</h3><p>If p=y′ appears in an equation, differentiate p as p′=y′′. Such a relation is not an ordinary curve F(x,y)=0, so do not apply the preceding partial-derivative shortcut while ignoring its p-variable. Keep the original branch and logarithm restrictions throughout.</p>''',
 ['Check the point lies on the original curve and record its domain.','Differentiate the relation, retaining every chain factor.','Find the first derivative at the required point.','Differentiate again before substituting numerical values.','Check any denominator used to define the local branch.'],
 ['Differentiate y² as 2yy′, not 2y.','Both factors of xy contribute a derivative.','Differentiate products involving y′ again.','Substitute the point after differentiating.','A zero branch denominator requires separate analysis.'],[
 E('I1','1 · A product term contributes twice',r'<p>Find y′ and y′′ at (1,2) on \(x^2+xy+y^2=7\).</p>',D(r'2x+y+(x+2y)y^{\prime}=0',r'y^{\prime}=-\frac45',r'2+2y^{\prime}+2(y^{\prime})^2+(x+2y)y^{\prime\prime}=0',r'y^{\prime\prime}=-\frac{42}{125}')+'<p>At the point, x+2y=5≠0. Insert the first derivative into the second equation; the squared derivative is positive even though y′ is negative.</p>','implicit',F='x**2+x*y+y**2-7',point=[1,2],first='-4/5',second='-42/125'),
 E('I2','2 · Differentiate a derivative product',r'<p>Find y′ and y′′ at (1,1) on \(y^3+xy=2\).</p>',D(r'(3y^2+x)y^{\prime}+y=0',r'y^{\prime}=-\frac14',r'(3y^2+x)y^{\prime\prime}+6y(y^{\prime})^2+2y^{\prime}=0',r'y^{\prime\prime}=\frac1{32}')+'<p>The product (3y²+x)y′ contributes a derivative of its coefficient and a derivative of y′. Differentiating the remaining y supplies the second y′ term.</p>','implicit',F='y**3+x*y-2',point=[1,1],first='-1/4',second='1/32'),
 E('I3','3 · A logarithm and its original domain',r'<p>On the branch xy&gt;0, find y′ and y′′ at (1,1) on \(\ln(xy)+y^2=1\).</p>',D(r'\frac1x+\frac{y^{\prime}}y+2yy^{\prime}=0',r'y^{\prime}=-\frac13',r'-\frac1{x^2}+\left(2-\frac1{y^2}\right)(y^{\prime})^2',r'\quad+\left(2y+\frac1y\right)y^{\prime\prime}=0',r'y^{\prime\prime}=\frac8{27}')+'<p>Use the derivative of ln(xy) directly on its domain. The calculation does not require extending ln x+ln y to branches where the individual logarithms are not real.</p>','implicit',F='log(x*y)+y**2-1',point=[1,1],first='-1/3',second='8/27'),
 E('I4','4 · The equation already contains p',r'<p>A twice-differentiable function satisfies \(p^3+2x^2+y^2=14\), where p=y′ and y(1)=2. Find y′(1) and y′′(1).</p>',D(r'p(1)^3=14-2-4=8,\qquad p(1)=2',r'3p^2p^{\prime}+4x+2yp=0',r'12p^{\prime}(1)+4+8=0',r'y^{\prime\prime}(1)=-1')+'<p>The real cube has one real root. Differentiating p³ gives 3p²p′, and p′ is the requested second derivative.</p>','derivative_relation',F='p**3+2*x**2+y**2-14',point=[1,2],first=2,second=-1)])
L('parametric','Parametric gradients and concavity','Differentiate with respect to x through the parameter.',
 'Calculate both derivatives, including the extra division by dx/dt.',before('implicit'),
 r'''<h3>Two coordinate functions, one curve</h3>'''+D(r'x=X(t),\qquad y=Y(t)',r'\frac{dy}{dx}=\frac{Y^{\prime}(t)}{X^{\prime}(t)}',r'\frac{d^2y}{dx^2}=\frac1{X^{\prime}(t)}\frac d{dt}\left(\frac{Y^{\prime}}{X^{\prime}}\right)')+r'''<p>Both formulae require X′(t)≠0. The second derivative is the rate of change of the gradient with x, not with t. Replacing it by Y′′/X′′ is incorrect.</p><h3>Useful combined form</h3>'''+D(r'\frac{d^2y}{dx^2}=\frac{X^{\prime}Y^{\prime\prime}-Y^{\prime}X^{\prime\prime}}{(X^{\prime})^3}')+r'''<p>This follows by differentiating the quotient and dividing once more by X′. It is useful for exact substitution, but retain the original domain of t before cancelling factors.</p><h3>Tangent exceptions</h3><p>At a regular horizontal tangent, Y′=0 and X′≠0. If X′=0 while Y′≠0, the tangent is vertical and a finite dy/dx does not exist. If both vanish, these shortcuts decide neither tangent direction nor regularity; investigate the local behaviour separately. A second-derivative sign change only describes an inflection when it occurs along a suitable regular branch.</p>''',
 ['Differentiate X and Y with respect to t.','Divide Y′ by X′ and retain excluded parameter values.','Differentiate this quotient with respect to t.','Divide by X′ once more.','Find coordinates from the original parametrisation, not from derivative ratios.'],
 ['Do not use Y′′/X′′ for the second derivative.','The extra division by X′ changes the sign in some domains.','Retain parameters cancelled from a ratio.','Check X′≠0 at a claimed horizontal tangent.','Give coordinates as well as parameter values when asked.'],[
 E('P1','1 · The second division matters',r'<p>For \(x=t^2+2\), \(y=t^3-t\), t&gt;0, find both derivatives in terms of t.</p>',D(r'X^{\prime}=2t,\qquad Y^{\prime}=3t^2-1',r'\frac{dy}{dx}=\frac{3t^2-1}{2t}',r'\frac d{dt}\left(\frac{dy}{dx}\right)=\frac32+\frac1{2t^2}',r'\frac{d^2y}{dx^2}=\frac{3t^2+1}{4t^3}')+'<p>The restriction t&gt;0 makes X′ positive and non-zero. The last expression is positive throughout this branch.</p>','parametric',X='t**2+2',Y='t**3-t',first='(3*t**2-1)/(2*t)',second='(3*t**2+1)/(4*t**3)'),
 E('P2','2 · A reciprocal parameter with a restriction',r'<p>For \(x=t+t^{-1}\), \(y=t-t^{-1}\), t&gt;1, find the gradient and second derivative at t=2.</p>',D(r'\frac{dy}{dx}=\frac{t^2+1}{t^2-1}',r'\frac{d^2y}{dx^2}=-\frac{4t^3}{(t^2-1)^3}',r'\left.\frac{dy}{dx}\right|_{t=2}=\frac53',r'\left.\frac{d^2y}{dx^2}\right|_{t=2}=-\frac{32}{27}')+'<p>The excluded value t=1 makes X′ vanish. Do not fill that missing derivative by cancellation.</p>','parametric_point',X='t+1/t',Y='t-1/t',at=2,first='5/3',second='-32/27'),
 E('P3','3 · A trigonometric parametrisation',r'<p>For \(x=3\sin t\), \(y=2\cos t\), 0&lt;t&lt;π/2, find both derivatives and evaluate the second at t=π/6.</p>',D(r'\frac{dy}{dx}=-\frac23\tan t',r'\frac{d^2y}{dx^2}=-\frac2{9\cos^3t}',r'\left.\frac{d^2y}{dx^2}\right|_{t=\pi/6}=-\frac{16\sqrt3}{81}')+'<p>The cosine is positive on this parameter interval, so the curve is concave down throughout it.</p>','parametric',X='3*sin(t)',Y='2*cos(t)',first='-2*tan(t)/3',second='-2/(9*cos(t)**3)',at='pi/6',at_second='-16*sqrt(3)/81'),
 E('P4','4 · Horizontal and vertical tangents differ',r'<p>For \(x=t^2\), \(y=t^3-3t\), find all horizontal tangents and examine the tangent at t=0.</p>',D(r'Y^{\prime}=3t^2-3=0\quad\Longrightarrow\quad t=\pm1',r't=-1:\ (x,y)=(1,2)',r't=1:\ (x,y)=(1,-2)',r't=0:\ X^{\prime}=0,\quad Y^{\prime}=-3\ne0')+'<p>At t=±1, X′=±2 is non-zero, so both are regular horizontal tangents. At (0,0) the tangent is vertical: x=0. This point is not another stationary point of y as a differentiable function of x.</p>','parametric_tangents',X='t**2',Y='t**3-3*t',horizontal=[-1,1],vertical=[0])])
L('functions','Hyperbolic and inverse-function derivatives','Derive the rules and respect the principal real branches.',
 'Differentiate compositions using justified inverse-function signs and domains.',before('parametric')+'<p>Review <a href="/courses/maths4u-9231-fp2?chapter=fp2_hyperbolic">Hyperbolic functions</a>, including principal inverses and logarithmic domains.</p>',
 r'''<h3>Start from exponentials</h3><p>Differentiating the exponential definitions gives the first two rules below; the quotient rule gives the third. Derivatives of the reciprocal functions then follow from differentiating a reciprocal.</p>'''+D(r'(\sinh x)^{\prime}=\cosh x,\quad(\cosh x)^{\prime}=\sinh x',r'(\tanh x)^{\prime}=\operatorname{sech}^2x',r'(\operatorname{sech}x)^{\prime}=-\operatorname{sech}x\tanh x',r'(\operatorname{cosech}x)^{\prime}=-\operatorname{cosech}x\operatorname{coth}x',r'(\operatorname{coth}x)^{\prime}=-\operatorname{cosech}^2x')+r'''<p>Use the chain rule for every non-trivial argument. Cosech and coth exclude zero from their domains.</p><h3>Undo the function, then choose the right sign</h3><p>For y=asinh x, differentiate sinh y=x. Cosh y is positive, so it becomes √(1+x²). For y=acosh x, the principal branch has y≥0; a finite derivative requires x&gt;1. For inverse tanh, use its real open domain.</p>'''+D(r'(\sinh^{-1}x)^{\prime}=\frac1{\sqrt{1+x^2}}',r'(\cosh^{-1}x)^{\prime}=\frac1{\sqrt{x^2-1}}\quad(x>1)',r'(\tanh^{-1}x)^{\prime}=\frac1{1-x^2}\quad(|x|<1)')+r'''<p>Inverse means a function that undoes the original map, not its reciprocal.</p>'''+D(r'(\sin^{-1}x)^{\prime}=\frac1{\sqrt{1-x^2}},\quad|x|<1',r'(\cos^{-1}x)^{\prime}=-\frac1{\sqrt{1-x^2}},\quad|x|<1',r'(\tan^{-1}x)^{\prime}=\frac1{1+x^2}')+r'''<p>The minus sign for inverse cosine follows because sin y≥0 on its principal interval. A composition can create a corner even when its expression is defined: a principal square root can introduce |x|, which must be analysed from both sides.</p>''',
 ['State the real domain and principal branch.','Derive or select the appropriate base derivative.','Multiply by the derivative of the inner function.','Differentiate again with all product and chain factors.','Check endpoints and both sides of any absolute value.'],
 ['Inverse hyperbolic functions are not reciprocals.','Acosh is defined at 1 but its ordinary derivative there is not finite.','Asin endpoints belong to its domain but not to its finite-derivative interval.','Do not replace √(x²) by x without a sign restriction.','A chain factor is needed for 2x just as for a more complicated argument.'],[
 E('H1','1 · Combine product and chain rules',r'<p>Find f′ and f′′ for \(f(x)=\cosh(2x)\sinh x\), and give both derivatives at zero.</p>',D(r'f^{\prime}=2\sinh(2x)\sinh x',r'\quad+\cosh(2x)\cosh x',r'f^{\prime\prime}=5\cosh(2x)\sinh x',r'\quad+4\sinh(2x)\cosh x',r'f^{\prime}(0)=1,\qquad f^{\prime\prime}(0)=0')+'<p>The inner argument 2x supplies a factor 2. Both terms of the first derivative must be differentiated again.</p>','function',f='cosh(2*x)*sinh(x)',first='2*sinh(2*x)*sinh(x)+cosh(2*x)*cosh(x)',second='5*cosh(2*x)*sinh(x)+4*sinh(2*x)*cosh(x)'),
 E('H2','2 · An inverse-sinh composition',r'<p>Find both derivatives of</p>'+D(r'y=\sinh^{-1}(3x+1)'),D(r'y^{\prime}=\frac3{\sqrt{1+(3x+1)^2}}',r'y^{\prime\prime}=-\frac{9(3x+1)}{[1+(3x+1)^2]^{3/2}}')+'<p>The radicand is positive for every real x. In the second derivative, the outside exponent −1/2 and the inside derivative 6(3x+1) combine with the original factor 3.</p>','function',f='asinh(3*x+1)',first='3/sqrt(1+(3*x+1)**2)',second='-9*(3*x+1)/(1+(3*x+1)**2)**(3/2)'),
 E('H3','3 · Domain before differentiating',r'<p>Find the domain and both derivatives of \(y=\tanh^{-1}(2x-1)\).</p>',D(r'-1<2x-1<1\quad\Longleftrightarrow\quad0<x<1',r'y^{\prime}=\frac1{2x(1-x)}',r'y^{\prime\prime}=-\frac{1-2x}{2x^2(1-x)^2}')+'<p>The derivative formula is used only inside the original open interval. Its algebraic expression outside that interval does not extend the real inverse-tanh function.</p>','function',f='atanh(2*x-1)',first='1/(2*x*(1-x))',second='-(1-2*x)/(2*x**2*(1-x)**2)'),
 E('H4','4 · A principal inverse produces a corner',r'<p>For \(f(x)=\cosh^{-1}(1+2x^2)\), decide whether f is differentiable at zero.</p>',D(r'f(x)=2\sinh^{-1}|x|',r'f^{\prime}(0^-)=-2,\qquad f^{\prime}(0^+)=2')+'<p>The identity follows by taking cosh of the non-negative quantity 2asinh|x|. The one-sided derivatives differ, so the function is continuous but has a corner at zero. A two-sided derivative-based Maclaurin expansion at zero is unavailable.</p>','corner',scale=2)])
L('geometry','Stationary points and local geometry','Find every regular candidate and justify its nature.',
 'Classify horizontal tangents, inflections and parameter boundary cases.',before('functions'),
 r'''<h3>Find all candidates in the actual domain</h3><p>For a smooth explicit function, solve y′=0. For F(x,y)=0 at a regular point, solve F=0 together with Fₓ=0, then check Fᵧ≠0. For a parametrisation solve Y′=0 while checking X′≠0. The denominator is part of the regularity test, not a factor to discard without comment.</p><h3>Nature needs evidence</h3><p>A positive second derivative at a stationary point gives a local minimum; a negative one gives a local maximum. If the second derivative vanishes, this test is inconclusive. Check the gradient or concavity on both sides. A stationary inflection has a horizontal tangent and a change of concavity, without a local extremum.</p><h3>Local versus global</h3><p>A local second-derivative test alone does not prove a global bound. To prove a global minimum, establish a gradient sign change on the whole domain, strict convexity with an attained critical point, or a completed square with the correct substituted range.</p><h3>Parameters and missing endpoints</h3><p>The open range of tanh is (−1,1). A stationary equation tanh x=k has a solution exactly for |k|&lt;1; at k=±1 it has no finite solution. Classify the equality cases separately. Tangent and normal equations also need separate treatment at zero or infinite gradient.</p>''',
 ['Solve the complete stationary conditions in the stated domain.','Check regularity and all denominator restrictions.','Use the second derivative when it is non-zero.','If it is zero, check signs on both sides.','Give every coordinate and justify any global claim separately.'],
 ['A zero second derivative does not prove an inflection.','A vertical tangent is not a stationary point of a smooth y(x).','Keep every branch satisfying the stated domain.','An asymptotic parameter endpoint may not produce a finite stationary point.','A local extremum is not automatically a global extremum.'],[
 E('G1','1 · Both stationary branches of an ellipse',r'<p>Find all stationary points of \((x-y)^2+4y^2=16\), classify them and give tangent and normal at the upper point.</p>',D(r'F_x=2(x-y)=0\quad\Longrightarrow\quad x=y',r'(x,y)=(2,2),\ (-2,-2)',r'y^{\prime\prime}=-\frac1{4y}\quad\text{at these points}',r'(2,2):\ y^{\prime\prime}=-\frac18',r'(-2,-2):\ y^{\prime\prime}=\frac18')+'<p>The upper point is a local maximum, with tangent y=2 and normal x=2. The lower is a local minimum. The branch denominators are non-zero at both points.</p>','stationary_implicit',F='(x-y)**2+4*y**2-16',points=[[2,2],[-2,-2]],seconds=['-1/8','1/8']),
 E('G2','2 · A unique global minimum',r'<p>Find the minimum of \(g(x)=\ln(\cosh x)-\frac{x}{2}\) on the real line.</p>',D(r'g^{\prime}=\tanh x-\frac12,\qquad g^{\prime\prime}=\operatorname{sech}^2x>0',r'x=\frac12\ln3',r'g_{\min}=\ln2-\frac34\ln3')+'<p>Tanh increases through 1/2 exactly once. The gradient is negative before and positive after, proving a unique global minimum. The positive second derivative independently confirms its local nature.</p>','minimum',f='log(cosh(x))-x/2',at='log(3)/2',value='log(2)-3*log(3)/4'),
 E('G3','3 · A stationary point without an extremum',r'<p>Classify the origin on \(f(x)=\sinh^{-1}x-x\).</p>',D(r'f^{\prime}=\frac1{\sqrt{1+x^2}}-1',r'f^{\prime\prime}=-\frac{x}{(1+x^2)^{3/2}}')+'<p>The first derivative is negative except at zero, so there is no gradient sign change. The second derivative is positive to the left and negative to the right. Thus (0,0) is a stationary point of inflection, with tangent y=0.</p>','inflection',f='asinh(x)-x'),
 E('G4','4 · Two parameter values, two points',r'<p>Find and classify all stationary points for \(x=t^2+1\), \(y=t^3-6t\), t real. Also locate the vertical tangent.</p>',D(r'Y^{\prime}=3t^2-6=0\quad\Longrightarrow\quad t=\pm\sqrt2',r't=-\sqrt2:\ (3,4\sqrt2),\quad y^{\prime\prime}=-\frac{3\sqrt2}{4}',r't=\sqrt2:\ (3,-4\sqrt2),\quad y^{\prime\prime}=\frac{3\sqrt2}{4}')+'<p>The upper point is a local maximum and the lower a local minimum. At t=0, X′=0 but Y′=−6≠0, giving a vertical tangent x=1 through (1,0), not an additional stationary point.</p>','parametric_tangents',X='t**2+1',Y='t**3-6*t',horizontal=['-sqrt(2)','sqrt(2)'],vertical=[0])])
L('maclaurin','Maclaurin polynomials and approximations','Connect derivatives, coefficients and justified local estimates.',
 'Find the requested first few terms and distinguish coefficients from derivatives.',before('geometry'),
 r'''<h3>Match derivatives at zero</h3>'''+D(r'f(x)=f(0)+f^{\prime}(0)x',r'\quad+\frac{f^{\prime\prime}(0)}{2!}x^2+\frac{f^{(3)}(0)}{3!}x^3+\cdots')+r'''<p>The coefficient of xⁿ is f⁽ⁿ⁾(0)/n!, not f⁽ⁿ⁾(0). To recover the derivative from a coefficient, multiply by the factorial. Here the aim is the first few terms requested, not a general formula for all n.</p><h3>Differentiate, compose or use a local relation</h3><p>Compute only as many derivatives as needed. For compositions, keep enough terms in each inner expansion: a leading x² may mean that only two terms of the outside series are needed through x⁴. On an implicit branch, verify the point and branch condition before finding the derivatives. If the question asks for derivation by differentiation, show those derivatives even when a known series could check the result.</p><h3>State what the truncation means</h3><p>Write the requested polynomial and an appropriate remainder order. Big-O records the order of omitted terms near zero; it does not by itself provide a numerical error bound at every x. An asymptotic approximation is an estimate, not an exact equality. The expansion must refer to a real, sufficiently smooth branch in a neighbourhood of zero.</p><h3>Extract the leading behaviour</h3><p>For a limit, cancel the terms explicitly and identify the first surviving power. Even or odd symmetry can explain missing powers. A corner such as a leading |x| term prevents the ordinary two-sided derivative-based expansion at zero.</p>''',
 ['Check the function has the required smooth real branch near zero.','Calculate the derivatives or permitted subsidiary series.','Divide each derivative by the correct factorial.','Retain every term up to the requested degree or number of non-zero terms.','Label estimates and justify any claimed error bound.'],
 ['A coefficient is not the corresponding derivative.','The first three non-zero terms need not have degrees 0,1,2.','Do not truncate the inner series too early.','An approximation is not an exact value.','A function defined at zero need not be differentiable there.'],[
 E('M1','1 · A whole cubic polynomial',r'<p>Find the Maclaurin polynomial through x³ for \(f(x)=\frac{e^{2x}}{1+x}\).</p>',D(r'f(0)=1,\quad f^{\prime}(0)=1',r'f^{\prime\prime}(0)=2,\quad f^{(3)}(0)=2',r'f(x)=1+x+x^2+\frac{x^3}{3}+O(x^4)')+'<p>Divide the second and third derivatives by 2! and 3!. Multiplying the exponential and reciprocal series gives the same coefficients, providing a separate check.</p>','series',f='exp(2*x)/(1+x)',degree=3,polynomial='1+x+x**2+x**3/3'),
 E('M2','2 · A fourth derivative from an even series',r'<p>Find \(\ln(\cosh2x)\) through x⁴, and deduce its fourth derivative at zero.</p>',D(r'\cosh2x=1+2x^2+\frac23x^4+O(x^6)',r'\ln(\cosh2x)=2x^2-\frac43x^4+O(x^6)',r'f^{(4)}(0)=4!\left(-\frac43\right)=-32')+'<p>The logarithm contributes both its first-order term and minus half the square of that term. Even symmetry rules out odd powers.</p>','series',f='log(cosh(2*x))',degree=4,polynomial='2*x**2-4*x**4/3'),
 E('M3','3 · Build the local implicit branch',r'<p>The branch through (0,0) satisfies \((1+x)y+y^2=x\). Find its polynomial through x³.</p>',D(r'y=ax+bx^2+cx^3+O(x^4)',r'a=1,\quad b+a+a^2=0',r'c+b+2ab=0',r'y=x-2x^2+6x^3+O(x^4)')+'<p>Equating successive coefficients gives a=1, b=−2 and c=6. The defining expression has derivative 1 with respect to y at the origin, so this is the unique smooth local branch through that point.</p>','implicit_series',F='(1+x)*y+y**2-x',polynomial='x-2*x**2+6*x**3',degree=3),
 E('M4','4 · A leading term determines a limit',r'<p>Find the first two non-zero terms of \(\sinh^{-1}(2x)-2x\) and hence its ratio to x³ as x→0.</p>',D(r'f^{(3)}(0)=-8,\qquad f^{(5)}(0)=288',r'\sinh^{-1}(2x)-2x=-\frac43x^3+\frac{12}{5}x^5+O(x^7)',r'\lim_{x\to0}\frac{\sinh^{-1}(2x)-2x}{x^3}=-\frac43')+'<p>The linear terms cancel. Divide the remaining expansion by x³; the higher powers then tend to zero. The odd symmetry explains the missing even powers.</p>','series',f='asinh(2*x)-2*x',degree=5,polynomial='-4*x**3/3+12*x**5/5')])
L('mixed','Mixed problems and later-topic links','Combine derivative methods while keeping prerequisites explicit.',
 'Apply chain-rule substitutions and local series without losing domains or initial data.',before('maclaurin')+'<p>The seven differential-equation extensions (Q2, Q13, Q26, Q34, Q39, Q44 and Q62) require linear first- and second-order differential-equation methods from later FP2 study. Q60, Q65 and Q77 require integration and, where supplied, the arc-length formula. Attempt those after learning the stated methods; the other four written problems consolidate this chapter.</p>',
 r'''<h3>Differentiate a substitution explicitly</h3><p>For w=φ(y), write both w′=φ′(y)y′ and w′′=φ′′(y)(y′)²+φ′(y)y′′. This explains how a nonlinear combination may become linear in w. Transform initial data too, including the first derivative.</p>'''+D(r'w=\phi(y)',r'w^{\prime\prime}=\phi^{\prime\prime}(y)(y^{\prime})^2+\phi^{\prime}(y)y^{\prime\prime}')+r'''<h3>Changing the independent variable</h3><p>If u=u(x), apply the chain rule twice. The second derivative contains two terms, because du/dx also depends on x.</p>'''+D(r'y_x=y_u u_x',r'y_{xx}=y_{uu}(u_x)^2+y_u u_{xx}')+r'''<p>Keep restrictions required for a reversible substitution, such as x&gt;0 for u=ln x, or a positive branch when recovering a square root. Check the recovered solution in the original relation and against all initial data.</p><h3>Approximations used in integrals</h3><p>A short local series can produce an approximate integral. Integrate the complete polynomial, state the integration interval, and label the result as approximate. A rigorous bound needs a separate argument controlling the remainder over the whole interval. These applications do not replace learning the later integration chapter.</p><h3>One method can check another</h3><p>Implicit differentiation can supply Maclaurin coefficients; an eliminated parametric equation can check both derivatives. Keep the domain obtained from the original parametrisation. A correct algebraic formula without that domain is not a complete description of the curve.</p>''',
 ['Identify the core skill and any later-topic prerequisites.','Write first and second chain-rule relations before substitution.','Transform domains and initial data together.','Solve only with justified later methods, then recover the original variable.','Check the original equation and label truncated-series estimates.'],
 ['The second derivative of a composition has two chain-rule terms.','Initial derivatives also change under substitution.','Recover the specified real branch, not both square roots automatically.','A truncated integral is approximate.','An eliminated equation must retain the parametrisation’s domain.'],[
 E('X1','1 · A dependent-variable substitution',r'<p>Near x=0, \(y^{\prime\prime}+(y^{\prime})^2+2y^{\prime}=4e^{-y}\), y(0)=ln2 and y′(0)=1/2. Use w=eʸ to recover y.</p>',D(r'w^{\prime\prime}+2w^{\prime}=4',r'w(0)=2,\qquad w^{\prime}(0)=1',r'w=2x+\frac32+\frac12e^{-2x}',r'y=\ln\left(2x+\frac32+\frac12e^{-2x}\right)')+'<p>Multiplying the original equation by eʸ gives the transformed equation. Solving it uses later linear-ODE methods. The logarithm is real on a neighbourhood of zero because its argument equals 2 there. Substitution verifies both initial conditions.</p>','ode_exp'),
 E('X2','2 · Change the independent variable twice',r'<p>For x&gt;0, solve \(x^2y^{\prime\prime}+xy^{\prime}-4y=0\) with y(1)=3 and y′(1)=2, using u=ln x.</p>',D(r'xy_x=y_u,\qquad x^2y_{xx}=y_{uu}-y_u',r'y_{uu}-4y=0',r'y=Ax^2+Bx^{-2}',r'A+B=3,\qquad2A-2B=2',r'y=2x^2+x^{-2}')+'<p>The x y′ term cancels the negative yᵤ term arising from the second derivative. Later constant-coefficient ODE methods give the two independent exponential solutions in u.</p>','ode_euler'),
 E('X3','3 · A labelled integral estimate',r'<p>Use the series through x⁴ for \(\ln(1+x^2)\) to estimate its integral from 0 to 1/5.</p>',D(r'\ln(1+x^2)=x^2-\frac{x^4}{2}+O(x^6)',r'\int_0^{1/5}\ln(1+x^2)\,dx',r'\quad\approx\left[\frac{x^3}{3}-\frac{x^5}{10}\right]_0^{1/5}=\frac{247}{93750}')+r'<p>This is an estimate, not an exact antiderivative evaluation. On this interval the next term of the alternating logarithm series bounds the pointwise error by \(x^6/3\), so the integral error is at most \(\frac{(1/5)^7}{21}\).</p>','integral',f='log(1+x**2)',polynomial='x**2-x**4/2',endpoint='1/5',answer='247/93750'),
 E('X4','4 · A local branch supplies a tangent and a series',r'<p>The branch through (0,0) satisfies \(y+xy^2=x+x^2\). Find y′(0), y′′(0), its tangent and its cubic Maclaurin polynomial.</p>',D(r'y^{\prime}+y^2+2xyy^{\prime}=1+2x',r'y^{\prime}(0)=1,\qquad y^{\prime\prime}(0)=2',r'y=x+x^2-x^3+O(x^4)',r'\text{tangent: }y=x')+'<p>The derivative with respect to y of the defining expression is 1 at the origin, so there is a smooth local branch. Substituting its proposed cubic into the original relation cancels all coefficients through degree 3.</p>','implicit_series',F='y+x*y**2-x-x**2',polynomial='x+x**2-x**3',degree=3)])
